// Markdown-zu-HTML Konverter
function md2html(md) {
  var text = md;
  // HTML-Entities
  text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  // Headings
  text = text.replace(/^### (.+)$/gm, '<h3>$1</h3>');
  text = text.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  text = text.replace(/^# (.+)$/gm, '<h1>$1</h1>');
  // Bold + Italic
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
  // Code
  text = text.replace(/`(.+?)`/g, '<code>$1</code>');
  // Markdown-Tabellen
  var lines = text.split('\n');
  var result = [];
  var inTable = false;
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line.match(/^\|.*\|$/)) {
      // Separator-Zeile überspringen
      if (line.match(/^\|[\s:|-]+\|$/)) continue;
      var cells = line.split('|').filter(function(c) { return c.trim() !== ''; });
      if (!inTable) {
        result.push('<table><thead><tr>');
        cells.forEach(function(c) { result.push('<th>' + c.trim() + '</th>'); });
        result.push('</tr></thead><tbody>');
        inTable = true;
      } else {
        result.push('<tr>');
        cells.forEach(function(c) { result.push('<td>' + c.trim() + '</td>'); });
        result.push('</tr>');
      }
    } else {
      if (inTable) { result.push('</tbody></table>'); inTable = false; }
      // Listen
      if (line.match(/^- /)) {
        result.push('<li>' + line.substring(2) + '</li>');
      } else if (line.match(/^\d+\. /)) {
        result.push('<li>' + line.replace(/^\d+\.\s*/, '') + '</li>');
      } else if (line === '') {
        result.push('<br>');
      } else {
        result.push('<p>' + line + '</p>');
      }
    }
  }
  if (inTable) result.push('</tbody></table>');
  return result.join('\n');
}

